 tx=Math.max(margin,Math.min(w-margin,tx));const headingBottom=game.querySelector('.snitch-heading').getBoundingClientRect().bottom-arena.getBoundingClientRect().top,flightTop=Math.min(h*.52,headingBottom+snitch.offsetHeight*.5+12);ty=Math.max(flightTop,Math.min(h-65,ty));if(reduced){flightX=w*.5;flightY=h*.43}else if(!freeze){const ease=1-Math.exp(-dt*(intro?5.8:now<approachableUntil?2.5:3.1));vx=(tx-flightX)*ease;vy=(ty-flightY)*ease;flightX+=vx;flightY+=vy}const roll=reduced?0:Math.max(-20,Math.min(20,vx*1.8)),scale=1+Math.sin(clock*.7)*.06;snitch.style.left=flightX+'px';snitch.style.top=flightY+'px';snitch.style.transform=`translate(-50%,-50%) perspective(600px) rotate(${roll}deg) rotateY(${Math.max(-25,Math.min(25,vx*2))}deg) scale(${scale})`;
